    u=emb_mm(us,role); t=emb_mm(ts,role)
    if idx is None: idx=np.arange(len(u))
    return np.concatenate([
        np.asarray(u[idx],np.float32),
        np.asarray(t[idx],np.float32)
    ],axis=1)

